// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;


interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IERC20Metadata is IERC20 {
    function name() external view returns (string memory);
    function symbol() external view returns (string memory);
    function decimals() external view returns (uint8);
}

/// @notice Minimal Context and Ownable (OpenZeppelin-like)
abstract contract Context {
    function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }
}

contract Ownable is Context {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    constructor() {
        _owner = _msgSender();
        emit OwnershipTransferred(address(0), _owner);
    }
    function owner() public view returns (address) {
        return _owner;
    }
    modifier onlyOwner() {
        require(owner() == _msgSender(), "Ownable: caller is not the owner");
        _;
    }
    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }
}

/// @notice Minimal ReentrancyGuard (OpenZeppelin-like)
abstract contract ReentrancyGuard {
    uint256 private _status;
    constructor() {
        _status = 1;
    }
    modifier nonReentrant() {
        require(_status != 2, "ReentrancyGuard: reentrant call");
        _status = 2;
        _;
        _status = 1;
    }
}

/* =========================
   DePayM USDC Staking (single-file)
   ========================= */

contract DePayMStaking is Ownable, ReentrancyGuard {
    IERC20Metadata public immutable USDC;
    uint8 public immutable tokenDecimals;

    uint256 public apr; // APR in basis points (100 = 1.00%)
    uint256 public constant YEAR = 365 days;

    struct StakeInfo {
        uint256 amount;
        uint256 rewardDebt;
        uint256 lastUpdated;
    }

    mapping(address => StakeInfo) public stakes;

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event RewardClaimed(address indexed user, uint256 reward);
    event AprUpdated(uint256 oldApr, uint256 newApr);
    event RewardsDeposited(address indexed from, uint256 amount);
    event RewardsWithdrawn(address indexed to, uint256 amount);

    constructor(address _usdc, uint256 _apr) {
        require(_usdc != address(0), "Invalid USDC address");
        USDC = IERC20Metadata(_usdc);
        tokenDecimals = USDC.decimals();
        apr = _apr;
    }

    // ---------- ADMIN ----------
    function setApr(uint256 newApr) external onlyOwner {
        require(newApr <= 5_000, "APR too high"); // max 50% (5000 bps)
        emit AprUpdated(apr, newApr);
        apr = newApr;
    }

    /// Owner can deposit USDC to fund rewards (owner must approve first)
    function depositRewards(uint256 amount) external onlyOwner {
        require(amount > 0, "Zero amount");
        require(USDC.transferFrom(msg.sender, address(this), amount), "Transfer failed");
        emit RewardsDeposited(msg.sender, amount);
    }

    /// Owner withdraw emergency funds
    function withdrawRewards(uint256 amount, address to) external onlyOwner {
        require(amount > 0, "Zero amount");
        require(to != address(0), "Invalid recipient");
        require(USDC.transfer(to, amount), "Transfer failed");
        emit RewardsWithdrawn(to, amount);
    }

    // ---------- VIEWS ----------
    function getDecimals() external view returns (uint8) {
        return tokenDecimals;
    }

    function pendingRewards(address user) public view returns (uint256) {
        StakeInfo memory s = stakes[user];
        if (s.amount == 0) return s.rewardDebt;

        uint256 timeDiff = block.timestamp - s.lastUpdated;
        uint256 yearlyReward = (s.amount * apr) / 10000;
        uint256 reward = (yearlyReward * timeDiff) / YEAR;

        return reward + s.rewardDebt;
    }

    function userStake(address user) external view returns (uint256) {
        return stakes[user].amount;
    }

    // ---------- CORE ----------
    function stake(uint256 amount) external nonReentrant {
        require(amount > 0, "Invalid amount");

        StakeInfo storage s = stakes[msg.sender];

        uint256 reward = pendingRewards(msg.sender);
        if (reward > 0) {
            s.rewardDebt = reward;
        }

        require(USDC.transferFrom(msg.sender, address(this), amount), "transferFrom failed");

        s.amount += amount;
        s.lastUpdated = block.timestamp;

        emit Staked(msg.sender, amount);
    }

    function unstake(uint256 amount) external nonReentrant {
        require(amount > 0, "Invalid amount");
        StakeInfo storage s = stakes[msg.sender];
        require(s.amount >= amount, "Insufficient staked");

        uint256 reward = pendingRewards(msg.sender);

        s.amount -= amount;
        s.rewardDebt = 0;
        s.lastUpdated = block.timestamp;

        require(USDC.transfer(msg.sender, amount), "transfer failed");

        if (reward > 0) {
            require(USDC.transfer(msg.sender, reward), "reward transfer failed");
            emit RewardClaimed(msg.sender, reward);
        }

        emit Unstaked(msg.sender, amount);
    }

    function claimRewards() external nonReentrant {
        uint256 reward = pendingRewards(msg.sender);
        require(reward > 0, "No rewards");

        StakeInfo storage s = stakes[msg.sender];
        s.rewardDebt = 0;
        s.lastUpdated = block.timestamp;

        require(USDC.transfer(msg.sender, reward), "reward transfer failed");

        emit RewardClaimed(msg.sender, reward);
    }
}

